/**
 * Worker entry point. It is OpenNext's worker plus a `scheduled` handler: every cron tick it calls
 * the app's own /api/cron/sync route through the self-reference binding. (wrangler.jsonc: "main": "worker.ts")
 */
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore .open-next/worker.js is generated by `opennextjs-cloudflare build`
import { default as handler } from "./.open-next/worker.js";

type Env = { WORKER_SELF_REFERENCE: { fetch: (url: string, init?: RequestInit) => Promise<Response> }; CRON_SECRET?: string };

export default {
  fetch: handler.fetch,
  async scheduled(_event: unknown, env: Env, ctx: { waitUntil(p: Promise<unknown>): void }) {
    ctx.waitUntil(
      env.WORKER_SELF_REFERENCE.fetch("https://internal/api/cron/sync", { method: "POST", headers: { authorization: `Bearer ${env.CRON_SECRET ?? ""}` } })
        .then(async (r) => console.log("[cron] sync", r.status, await r.text()))
        .catch((e) => console.error("[cron] sync failed", e)),
    );
  },
};
